import base64,datetime,hashlib,json,os,re,shlex,subprocess,sys
from pathlib import Path
os.umask(0o077)
P=Path(__file__).resolve().parent
M=json.loads((P/'state.json').read_text())
E=Path(M['evidence'])
ROOT=Path('<repository>')
ENV=dict(os.environ,KUBECONFIG=M['kubeconfig'],PYTHONDONTWRITEBYTECODE='1',PATH=str(ROOT/'.tmp/bin')+':'+os.environ['PATH'])
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def save(name,value):
    with (E/name).open('x') as f: json.dump(value,f,indent=2,sort_keys=True);f.write('\n')
def phase(name,**data):
    with (E/'phases.jsonl').open('a') as f: f.write(json.dumps(dict(phase=name,recorded_at_utc=now(),source_sha=M['source_sha'],**data))+'\n')
def run(args,input=None,env=None,timeout=60,binary=False,check=True,label='operator-command'):
    r=subprocess.run([str(a) for a in args],input=input,capture_output=True,text=not binary,env=env or ENV,timeout=timeout)
    if check and r.returncode:
        path=P/('failure-'+str(len(list(P.glob('failure-*'))))+'.log')
        path.write_bytes((r.stdout+r.stderr).encode() if not binary else r.stdout+r.stderr)
        phase(label,success=False,exit_code=r.returncode)
        raise RuntimeError(label+' failed; exit='+str(r.returncode)+'; protected diagnostics retained')
    return r if not check else r.stdout

def k(*args,**kw): return run(['kubectl','--request-timeout=20s',*args],**kw)
def kj(*args): return json.loads(k(*args,'-o','json'))
def aj(*args): return json.loads(run(['az',*args,'-o','json']))
def secret(namespace,name,key): return base64.b64decode(kj('-n',namespace,'get','secret',name)['data'][key]).decode()
def metadata(): (P/'state.json').write_text(json.dumps(M))
def env_values():
    path=Path('<existing-approved-admin-env>')
    assert path.stat().st_mode & 0o077 == 0
    d={}
    for line in path.read_text().splitlines():
        if '=' in line and not line.strip().startswith('#'):
            key,val=line.split('=',1);parts=shlex.split(val);d[key.removeprefix('export ').strip()]=' '.join(parts)
    return d

def sql(query,ns='forgejo',pod='p7-checkpoint-db',admin=False,database=None):
    if admin:
        args=['env','-u','PGPASSWORD','psql','-X','-h',M['pg_host'],'-U','forgejoadmin','-d',database or 'postgres','-W','-v','ON_ERROR_STOP=1','-tA','-c',query]
        return k('-n',ns,'exec','-i',pod,'--',*args,input=env_values()['POSTGRESQL_ADMIN_PASSWORD']+'\n',label='postgres-admin-command')
    args=['psql','-X','-v','ON_ERROR_STOP=1','-tA']
    if database:args+=['-d',database]
    return k('-n',ns,'exec',pod,'--',*args,'-c',query,label='postgres-app-command')
def parse_env(path):
    d={}
    for line in Path(path).read_text().splitlines():
        key,val=line.split('=',1);d[key]=' '.join(shlex.split(val))
    return d
def journey(mode,directory,label=None,endpoint=None,recovery=False,admin=None):
    env=dict(ENV,FORGEJO_URL='https://'+M['hostname'],JOURNEY_DIR=str(directory))
    if endpoint:
        env.update(JOURNEY_ENDPOINT_URL=endpoint,JOURNEY_ENVIRONMENT='local-k3d')
    else:
        env.update(JOURNEY_ENVIRONMENT='azure-aks',JOURNEY_DNS_OVERRIDE=M['ingress_ip'])
    if recovery:env['RECOVERY_FIXTURE']='1'
    if mode=='create':
        env.update(FORGEJO_ADMIN_USERNAME=admin[0] if admin else secret('forgejo','forgejo-admin','username'),FORGEJO_ADMIN_PASSWORD=admin[1] if admin else secret('forgejo','forgejo-admin','password'))
    args=['bash',str(ROOT/'tests/e2e/forgejo-developer-journey.sh'),mode]+([label] if label else [])
    out=run(args,env=env,label='journey-'+mode,timeout=None)
    return out
